//! =[ tomet-benches ]
//!
//! Inputs shared by every criterion benchmark in this package. Each input is
//! checked against the real parser before anything is timed, so a bench can
//! never end up measuring an error path.
//!
//! =[ Sources ]
//!
//! - (`fixtures`) The frozen in-repo corpus from `tomet-tests`; always there.
//! - (`synth_doc`)| One document generated by `tomet-synth` at a chosen size.
//!                | The same bytes for the same arguments (fixed [`SEED`]).
//! - (`external_sets`)| Real data from a `tomet-corpus` checkout. Present only
//!                    | when `TOMET_CORPUS_DIR` points at one; otherwise empty,
//!                    | never an error.
//!
//! `tomet-synth` writes plain text and knows nothing of this repository, so the
//! check that its output parses lives here, in `assert_parses`.
//!
//! =[ Running ]
//!
//! ```text
//! cargo bench -p tomet-benches                     # fixtures + synthetic
//! TOMET_CORPUS_DIR=../tomet-corpus cargo bench -p tomet-benches   # + real data
//! TOMET_BENCH_LARGE=1 cargo bench -p tomet-benches                # + 1 MB documents
//! cargo bench -p tomet-benches -- --test           # run each bench once, no timing
//! ```

use std::path::{Path, PathBuf};

use tomet_synth::{Config, Corpus};

/// Seed of every synthetic document. Changing it voids every recorded
/// baseline, exactly like changing the generator's stream does.
pub const SEED: u64 = 0x746f_6d65_74;

/// Environment variable naming a `tomet-corpus` checkout.
pub const CORPUS_DIR_ENV: &str = "TOMET_CORPUS_DIR";

/// Data sets looked up under `<TOMET_CORPUS_DIR>/data/`.
const EXTERNAL_SETS: &[&str] = &["wikipedia/pages", "aozora/pages", "handwritten", "examples"];

#[derive(Debug, Clone)]
pub struct Input {
    pub name: String,
    pub text: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Flavor {
    /// Encyclopedia-like: headings, links, nested lists, tables.
    Wiki,
    /// Literary: ruby and dialogue.
    Prose,
}

impl Flavor {
    pub fn label(self) -> &'static str {
        match self {
            Flavor::Wiki => "synth-wiki",
            Flavor::Prose => "synth-prose",
        }
    }
}

/// Every fixture the parser is expected to accept.
pub fn fixtures() -> Vec<Input> {
    tomet_tests::parseable_corpus()
        .into_iter()
        .map(|(rel, text)| Input {
            name: rel.display().to_string(),
            text,
        })
        .collect()
}

/// One synthetic document of roughly `bytes` bytes (it overshoots by at most
/// one block).
pub fn synth_doc(flavor: Flavor, bytes: usize) -> Input {
    let config = match flavor {
        Flavor::Wiki => Config::wiki(),
        Flavor::Prose => Config::prose(),
    };
    let doc = Corpus::new(SEED, config.with_target_bytes(bytes)).doc(0);
    Input {
        name: format!("{}/{bytes}", flavor.label()),
        text: doc.text,
    }
}

/// Real data sets from `TOMET_CORPUS_DIR`, as `(set name, files)`.
///
/// A set that is missing, or whose files all fail to parse, is left out. A
/// file that fails to parse is dropped and counted on stderr: real data is
/// allowed to be imperfect, a benchmark is not allowed to time its failure.
pub fn external_sets() -> Vec<(String, Vec<Input>)> {
    let Some(root) = std::env::var_os(CORPUS_DIR_ENV).map(PathBuf::from) else {
        return Vec::new();
    };
    let mut sets = Vec::new();
    for set in EXTERNAL_SETS {
        let dir = root.join("data").join(set);
        let mut paths = Vec::new();
        collect_tmt(&dir, &mut paths);
        paths.sort();
        let total = paths.len();
        let files: Vec<Input> = paths
            .into_iter()
            .filter_map(|path| {
                let text = std::fs::read_to_string(&path).ok()?;
                tomet_parser::parse_document(&text).ok()?;
                Some(Input {
                    name: path
                        .strip_prefix(&dir)
                        .unwrap_or(&path)
                        .display()
                        .to_string(),
                    text,
                })
            })
            .collect();
        if files.len() < total {
            eprintln!(
                "{CORPUS_DIR_ENV}: {set}: skipped {} of {total} file(s) that do not parse",
                total - files.len()
            );
        }
        if !files.is_empty() {
            sets.push(((*set).replace('/', "-"), files));
        }
    }
    sets
}

/// Panics, naming the input, unless `tomet-parser` accepts it.
pub fn assert_parses(input: &Input) {
    if let Err(e) = tomet_parser::parse_document(&input.text) {
        panic!("benchmark input `{}` does not parse: {e}", input.name);
    }
}

/// Total size of a set, for throughput.
pub fn total_bytes(inputs: &[Input]) -> u64 {
    inputs.iter().map(|i| i.text.len() as u64).sum()
}

fn collect_tmt(dir: &Path, acc: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.file_name().is_some_and(|f| f == ".git") {
            continue;
        }
        if path.is_dir() {
            collect_tmt(&path, acc);
        } else if path.extension().is_some_and(|e| e == "tmt") {
            acc.push(path);
        }
    }
}
